SELECT history_id as historyId, attendance_id as attendanceId, employee_id as employeeId, actor_employee_id as actorEmployeeId, action_type as actionType, reason as reason, work_date as workDate, before_check_in_time as beforeCheckInTime, after_check_in_time as afterCheckInTime, before_check_out_time as beforeCheckOutTime, after_check_out_time as afterCheckOutTime, before_tardy_reason as beforeTardyReason, after_tardy_reason as afterTardyReason, before_status as beforeStatus, after_status as afterStatus, before_closed as beforeClosed, after_closed as afterClosed, created_at as createdAt FROM attendance_history WHERE DATE_FORMAT(work_date, '%Y-%m') = #{targetMonth}
AND employee_id = #{employeeId}
ORDER BY created_at DESC, history_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM attendance_history
WHERE DATE_FORMAT(work_date, '%Y-%m') = #{targetMonth}

    AND employee_id = #{employeeId}
